data.variablesTransform:
(
  /* There is a chance that the end date is before the start */
  $start := $moment($state.context.REQUEST.value.after.startAt).tz($state.context.TIMEZONE, true);
  $end := $moment($state.context.REQUEST.value.after.endAt).tz($state.context.TIMEZONE, true);

  $end := $moment($end).isBefore($moment($start)) ? $moment($end).add(1,'day') : $end; 

  $durationSeconds := $moment($end).diff($start,'seconds');

  {
    "payload": $state.context.SHIFTGROUP.(
      $id := calendarId & '::' & $state.context.REQUEST.value.after.id;
      {
        "create": {
          "id": $id,
          "calendarId": calendarId,
          "calendarEventTypeId": "available",
          "title": $state.context.REQUEST.value.after.name,
          "description": "Created & Maintained by Fuuz system event.",
          "priority": 0,
          "eventJson": {
            "duration": $durationSeconds * 1000,
            "rrule": {
              "dtstart": $dtstart,
              "freq": "daily",
              "byweekday": $state.context.REQUEST.value.after.[
                (sunday) ? 6,
                (monday) ? 0,
                (tuesday) ? 1,
                (wednesday) ? 2,
                (thursday) ? 3,
                (friday) ? 4,
                (saturday) ? 5
              ]
            },
            "allDay": false,
            "recurring": true,
            "start": $start,
            "end": $end,
            "display": "background"
          }
        },
        "update": {
          "calendarEventTypeId": "available",
          "title": $state.context.REQUEST.value.after.name,
          "description": "Created & Maintained by Fuuz system event.",
          "priority": 0,
          "eventJson": {
            "duration": $durationSeconds * 1000,
            "rrule": {
              "dtstart": $dtstart,
              "freq": "daily",
              "byweekday": $state.context.REQUEST.value.after.[
                (sunday) ? 6,
                (monday) ? 0,
                (tuesday) ? 1,
                (wednesday) ? 2,
                (thursday) ? 3,
                (friday) ? 4,
                (saturday) ? 5
              ]
            },
            "allDay": false,
            "recurring": true,
            "start": $start,
            "end": $end,
            "display": "background"
          }
        },
        "where": {
          "id": $id
        }
      }
    )
  }   
)

data.query:
query shiftGroup($where:ShiftGroupWhereInput!){
  shiftGroup(where:$where) {
    edges {
      node {
        id
        name
        calendarId
      }
    }
  }

  setting(where: { id: { _eq: "TimeZone" } }) {
    edges {
      node {
        defaultValue
      }
    }
  }
}

